import {finaleState,canMeetFinalUnique} from './finale-rules.js?v=0.90.19';
const keys=['spore-rim','spore-depths','spore-bridge','spore-grotto','spore-canopy','road','burial','falls','terraces','guan','fei','cayfen','gallery','spore','darius','ramelle','fortress','mirror','shop','inn','sanctuary','cayfen-hall'];
const props=['rune-shelter','rune-faith','rune-crossing','windlass','inscription'];
export const FINALE_ASSETS=Object.fromEntries([...keys.map(k=>['finale-'+k,'../finale/env-'+k+(k.startsWith('spore-')?'.svg':'.webp')]),...props.map(k=>['finale-prop-'+k,'../finale/prop-'+k+'.webp'])]);
export function drawFinaleMap(c,m,asset){if(!m?.finale)return false;asset(c,'finale-'+m.finaleArt,0,0,48,32);for(const p of m.spots){const rune=p.id.match(/^fn-guan-rune-(.+)$/),kind=rune?'rune-'+rune[1]:p.id.startsWith('fn-fei-weight-')?'windlass':(/^fn-(guan|fei)-clue$/.test(p.id)||p.id.startsWith('fn-rare-record-'))?'inscription':null;if(kind)asset(c,'finale-prop-'+kind,p.x-1,p.y-2,2,3);}return true;}
export function drawFinaleCreatures(c,s,room,drawCreature){const q=finaleState(s);if(room==='burialGrove'&&q.legacies&&!q.legacyDepartureSeen)for(const [key,x]of [['pate',21],['trade',28]]){const u=[...(s.party||[]),...(s.reserve||[])].find(u=>u.uid===q.legacies[key].uid);if(u?.hp>0&&!u.dead&&u.uid!==s.leadUid)drawCreature(c,u,x,20,40);}for(const [r,key,x,y]of [['guanShrine','guan',24,10],['feiCrossing','fei',28,14],['sporeCrown','crux',28,16],['sunTerraces','suncub',24,7],['sporeDepths','gehennuar',26,15]])if(room===r&&canMeetFinalUnique(s,key))drawCreature(c,{species:{id:key==='guan'?'183':key==='fei'?'175':key==='suncub'?'186':key==='gehennuar'?'166':'174'}},x,y,key==='crux'?84:60);}
export function commissionCanvas(canvas,work,baseImage=null){const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;const w=canvas.width,h=canvas.height;c.fillStyle='#e9dfc6';c.fillRect(0,0,w,h);if(baseImage?.complete&&baseImage.naturalWidth)c.drawImage(baseImage,0,0,w,h);return c;}
